import 'dart:math';

import 'package:flutter/material.dart';
import 'package:provider/provider.dart';

import '../../models/screen_config.dart';
import '../../services/playback_controller.dart';
import '../../theme/app_palette.dart';
import '../../theme/app_typography.dart';
import 'base_hero_container.dart';
import 'hero_title_block.dart';

/// Dot visualisation embedded in the Void hero slot: a single pulsing circle whose radius tracks the spectrum's bass energy (Void chrome owns transport). When [DotScreenConfig.showSongInfo] is true (B-020) the active track's Artist (H1) / Song (H2) overlay the top of the band in a [Stack] above the centered dot, using the shared [HeroTitleBlock] (B-046). The dot is clamped to a fraction of the smallest dimension so it never overflows.
class DotHero extends StatelessWidget {
  const DotHero({super.key, required this.config});

  final DotScreenConfig config;

  double _radiusFor(
    List<double> spectrum,
    double minAllowed,
    double maxAllowed,
  ) {
    final maxClamp = maxAllowed.clamp(0.0, double.infinity);
    final minClamp = min(config.minDotSize, maxClamp).clamp(0.0, double.infinity);

    if (spectrum.isEmpty) return min(minAllowed, minClamp);

    var bass = 0.0;
    for (var i = 0; i < min(spectrum.length, 3); i++) {
      bass = max(bass, spectrum[i]);
    }

    final r = config.minDotSize +
        bass * bass * config.sensitivity * (config.maxDotSize - config.minDotSize);

    return r.clamp(min(minAllowed, minClamp), minClamp.clamp(0.0, maxClamp));
  }

  @override
  Widget build(BuildContext context) {
    final palette = Theme.of(context).extension<AppPalette>()!;

    // read (not watch): the dot animates off [spectrumListenable] below, so this
    // widget must NOT rebuild on every controller notify.
    final player = context.read<PlaybackController>();

    // Only watch for track changes: the overlay sizing needs the worst-case
    // heading height (2 lines each) to keep the dot from intersecting.
    final hasTrack = context.select<PlaybackController, bool>(
      (p) => p.songInfo?.track != null,
    );
    final hasArtist = context.select<PlaybackController, bool>(
      (p) => (p.songInfo?.track.artist?.trim().isNotEmpty ?? false),
    );

    return LayoutBuilder(
      builder: (context, constraints) {
        final baseMaxAllowed =
            min(constraints.maxWidth, constraints.maxHeight) / 2;
        var maxAllowed = baseMaxAllowed;

        if (config.showSongInfo) {
          final typography = Theme.of(context).extension<AppTypography>()!;
          final scaler =
              MediaQuery.maybeOf(context)?.textScaler ?? TextScaler.noScaling;

          // B-026-ish: reserve the worst-case overlay height (2 lines each, the
          // H1→H2 gap + a small buffer) so the pulsing dot never intersects it.
          const double lineHeightMultiplier = 1.18;
          const double overlayTopPadding = 12.0;
          const double textToDotGap = 8.0;
          const double textBlockSafetyBuffer = 8.0;

          final h1Size = scaler.scale(typography.heroSize * config.textScale);
          final h2Size = scaler
              .scale(typography.heroSize * heroSongSizeFactor * config.textScale);

          final reservedTextHeight = hasTrack
              ? (hasArtist
                  ? h1Size * lineHeightMultiplier * 2 +
                      8 +
                      h2Size * lineHeightMultiplier * 2
                  : h2Size * lineHeightMultiplier * 2)
              : h1Size * lineHeightMultiplier * 2;

          final verticalSafeMax =
              constraints.maxHeight / 2 - overlayTopPadding -
                  reservedTextHeight - textToDotGap -
                  textBlockSafetyBuffer;

          maxAllowed = min(baseMaxAllowed, verticalSafeMax.clamp(0.0, double.infinity));
        }

        final minAllowed = 0.0;

        return BaseHeroContainer(
          child: Stack(
            children: [
              // Pulsing dot — always centered. Only this subtree repaints per
              // spectrum frame (RepaintBoundary-isolated).
              Center(
                child: RepaintBoundary(
                  child: AnimatedBuilder(
                    animation: player.spectrumListenable,
                    builder: (context, _) {
                      final r = _radiusFor(player.spectrumData, maxAllowed);
                      return Container(
                        width: r * 2,
                        height: r * 2,
                        decoration: BoxDecoration(
                          color: palette.fgPrimary
                              .withValues(alpha: config.dotOpacity),
                          shape: BoxShape.circle,
                        ),
                      );
                    },
                  ),
                ),
              ),
              // Optional song-info overlay pinned to the top of the hero band (B-020), above the dot.
              if (config.showSongInfo)
                Positioned(
                  left: 0,
                  right: 0,
                  top: 12,
                  child: Opacity(
                    opacity: config.textOpacity.clamp(0.0, 1.0),
                    child: HeroTitleBlock(textScale: config.textScale),
                  ),
                ),
            ],
          ),
        );
      },
    );
  }
}

